a = int(input('a: '))
s = input('s: ')
b = int(input('b: '))

if s == '+':
    print(f'{a} {s} {b} = {a + b}')
elif s == '-':
    print(f'{a} {s} {b} = {a - b}')
elif s == '*':
    print(f'{a} {s} {b} = {a * b}')
elif s == '/':
    try:
        if b == 0:
            raise ZeroDivisionError("Деление на нуль")
        result = a / b
        print(f'{a} {s} {b} = {result}')
    except ZeroDivisionError:
        print('Нельзя делить на нуль!')
else:
    print('Недопустимая операция')
